// frontend.md §5.3: generated files start with a `Generated by <tool>` header naming an existing tool and are
// marked `linguist-generated=true` in .gitattributes. Today's gaps are in generated-markers-baseline.json until
// step E1 adds the headers (in the generators) and the .gitattributes lines, then deletes the baseline.
import test from 'node:test';
import assert from 'node:assert/strict';
import {
  compareCounts, generatedGaps, generatedHeader, generatedSourceFiles, listSources, readJson, readSource, withoutComments,
} from './scan.mjs';

const asCounts = map => Object.fromEntries(Object.entries(map).map(([entry, gaps]) => [entry, Object.fromEntries(gaps.map(g => [g, 1]))]));
const baseline = asCounts(withoutComments(readJson('generated-markers-baseline.json')));
const { gaps, gitAvailable } = generatedGaps();

function ratchet(t, kinds, label) {
  const pick = map => Object.fromEntries(Object.entries(map)
    .map(([entry, keys]) => [entry, Object.fromEntries(Object.entries(keys).filter(([k]) => kinds.includes(k)))])
    .filter(([, keys]) => Object.keys(keys).length));
  const { regressions, improvements } = compareCounts(pick(asCounts(gaps)), pick(baseline));
  for (const line of improvements) t.diagnostic(`fixed, remove it from generated-markers-baseline.json: ${line}`);
  assert.deepEqual(regressions, [], `${label}\n  ${regressions.join('\n  ')}`);
}

test('every listed generated source exists exactly once under client/src', () => {
  const bad = generatedSourceFiles().filter(g => g.files.length !== 1).map(g => `${g.entry}: ${g.files.length} matches`);
  assert.deepEqual(bad, []);
});

test('generated sources start with a `Generated by <existing tool>` header (ratchet)', t => {
  ratchet(t, ['header', 'missing', 'ambiguous'], 'generated sources without a header naming an existing tool');
});

test('generated files are linguist-generated in .gitattributes (ratchet)', t => {
  if (!gitAvailable) { t.skip('git is not available to evaluate .gitattributes'); return; }
  ratchet(t, ['gitattributes', 'missing'], 'generated files without linguist-generated=true');
});

test('no unlisted client/src file carries a generated header', () => {
  const listed = new Set(generatedSourceFiles().flatMap(g => g.files));
  const unlisted = listSources(['.ts', '.css']).filter(f => !listed.has(f) && generatedHeader(readSource(f)).generated);
  assert.deepEqual(unlisted, [], 'add the file to GENERATED_SOURCES in tests/frontend/architecture/scan.mjs');
});
